    {
        Schema::create('services', function (Blueprint $table) {
            $table->id();
            $table->string('name');                                   // e.g. Men haircut
            $table->text('description')->nullable();
            $table->unsignedSmallInteger('duration_minutes');         // e.g. 30
            $table->unsignedSmallInteger('break_minutes')->default(0);// clean-up break, e.g. 5 or 10
            $table->unsignedSmallInteger('max_parallel_bookings')->default(1); // clients per slot, e.g. 5
